-- Momo v3.49 — Support-assisted Knowledge Base automatic save after approval
-- Run in Supabase SQL Editor, then reindex Momo Support knowledge from
-- Admin > Support > Knowledge Base > Reindexar documentação.
-- No schema change is required. This migration only updates Support documentation.

update public.knowledge_entries
set
  category = 'Knowledge Base',
  title = 'Managing the Knowledge Base',
  content = 'The Knowledge Base is managed by an organization Owner. In Portal > Knowledge Base, an Owner can add manual knowledge with Title, Category and Content, choose Public or Internal visibility, choose Published or Draft status, and save the entry. A public published manual entry is embedded/indexed when it is saved, so Reindex is not mandatory after every manual entry; Reindex is available to refresh public published knowledge after broader changes. Website knowledge can also be generated by analysing the organization public website. Running website analysis again replaces website-sourced entries while preserving manual entries. Before saving new manual business information, Momo Support should recommend that the client paste the raw information into Support so it can be checked and prepared as a clear Knowledge Base draft. For an authenticated Owner, after Support shows the final Title, Category and Content and the Owner explicitly confirms that the draft is correct and asks to add/save it, Momo Support can create that entry directly as Public + Published and index it for the website agent. Members may prepare wording with Support but cannot save Knowledge Base changes.',
  visibility = 'public',
  status = 'published',
  embedding = null,
  updated_at = now()
where agent_key = 'momo-support'
  and slug = 'momo-support-knowledge-base';

insert into public.knowledge_entries (
  slug, agent_key, category, title, content, visibility, status
)
select
  'momo-support-knowledge-base',
  'momo-support',
  'Knowledge Base',
  'Managing the Knowledge Base',
  'The Knowledge Base is managed by an organization Owner. In Portal > Knowledge Base, an Owner can add manual knowledge with Title, Category and Content, choose Public or Internal visibility, choose Published or Draft status, and save the entry. A public published manual entry is embedded/indexed when it is saved, so Reindex is not mandatory after every manual entry; Reindex is available to refresh public published knowledge after broader changes. Website knowledge can also be generated by analysing the organization public website. Running website analysis again replaces website-sourced entries while preserving manual entries. Before saving new manual business information, Momo Support should recommend that the client paste the raw information into Support so it can be checked and prepared as a clear Knowledge Base draft. For an authenticated Owner, after Support shows the final Title, Category and Content and the Owner explicitly confirms that the draft is correct and asks to add/save it, Momo Support can create that entry directly as Public + Published and index it for the website agent. Members may prepare wording with Support but cannot save Knowledge Base changes.',
  'public',
  'published'
where not exists (
  select 1 from public.knowledge_entries
  where agent_key = 'momo-support'
    and slug = 'momo-support-knowledge-base'
);

update public.knowledge_entries
set
  category = 'Knowledge Base',
  title = 'Preparing and saving Knowledge Base entries with Momo Support',
  content = 'Momo Support can help an authenticated client prepare wording before a manual Knowledge Base entry is saved. The client can paste raw business information into Support. Support may rewrite only for clarity, structure and self-contained wording; it must preserve every supplied fact, condition, exception, limitation, name, price, amount, date, duration, unit, location and policy, and it must not invent or silently remove information. If the source is ambiguous, contradictory or missing context needed for a reliable statement, Support asks a concise clarifying question before producing the final draft. Good Knowledge Base wording is factual, direct, self-contained and focused on one coherent topic where practical. When ready, Support shows the exact Title, Category and Content and asks the client to review them. An authenticated Owner can then explicitly approve and ask Support to add/save the entry. Only after that explicit approval, Support creates the entry as Public + Published and generates its embedding immediately, so no manual Reindex is needed for that entry. If the Owner asks for a correction, Support must revise and show the full draft again before saving. Members can prepare and review drafts but cannot save Knowledge Base changes; an Owner must apply them. The automatic Support save flow does not currently create Internal or Draft entries; those visibility/status choices remain available through Portal > Knowledge Base.',
  visibility = 'public',
  status = 'published',
  embedding = null,
  updated_at = now()
where agent_key = 'momo-support'
  and slug = 'momo-support-knowledge-drafting';

insert into public.knowledge_entries (
  slug, agent_key, category, title, content, visibility, status
)
select
  'momo-support-knowledge-drafting',
  'momo-support',
  'Knowledge Base',
  'Preparing and saving Knowledge Base entries with Momo Support',
  'Momo Support can help an authenticated client prepare wording before a manual Knowledge Base entry is saved. The client can paste raw business information into Support. Support may rewrite only for clarity, structure and self-contained wording; it must preserve every supplied fact, condition, exception, limitation, name, price, amount, date, duration, unit, location and policy, and it must not invent or silently remove information. If the source is ambiguous, contradictory or missing context needed for a reliable statement, Support asks a concise clarifying question before producing the final draft. Good Knowledge Base wording is factual, direct, self-contained and focused on one coherent topic where practical. When ready, Support shows the exact Title, Category and Content and asks the client to review them. An authenticated Owner can then explicitly approve and ask Support to add/save the entry. Only after that explicit approval, Support creates the entry as Public + Published and generates its embedding immediately, so no manual Reindex is needed for that entry. If the Owner asks for a correction, Support must revise and show the full draft again before saving. Members can prepare and review drafts but cannot save Knowledge Base changes; an Owner must apply them. The automatic Support save flow does not currently create Internal or Draft entries; those visibility/status choices remain available through Portal > Knowledge Base.',
  'public',
  'published'
where not exists (
  select 1 from public.knowledge_entries
  where agent_key = 'momo-support'
    and slug = 'momo-support-knowledge-drafting'
);
